            if (hrc.getRole().equals(Role.NAMENODE) && hrc.getHostName().equals("h1")) {
                namenodeInstall = hrc;
            } else if (hrc.getRole().equals(Role.HDFS_CLIENT) && hrc.getHostName().equals("h3")) {
                clientInstall = hrc;
