@Test
@SuppressWarnings("unchecked")
public /**
 * Tests the case when all service components are in MM (so we base on MM
 * components state when calculating entire service state)
 */
void testDefaultServiceState_All_Components_In_MM() throws Exception {
    AmbariManagementController managementController = createMock(AmbariManagementController.class);
    Clusters clusters = createNiceMock(Clusters.class);
    Cluster cluster = createNiceMock(Cluster.class);
    AmbariMetaInfo ambariMetaInfo = createNiceMock(AmbariMetaInfo.class);
    StackId stackId = createNiceMock(StackId.class);
    ComponentInfo componentInfo = createStrictMock(ComponentInfo.class);
    /*
     * Any component is started, all other are stopped - service is considered STARTED
     */
    ServiceComponentHostResponse shr1 = new ServiceComponentHostResponse("C1", "YARN", "RESOURCEMANAGER", "Host100", "INSTALLED", "", null, null, null);
    shr1.setMaintenanceState(MaintenanceState.ON.toString());
    ServiceComponentHostResponse shr2 = new ServiceComponentHostResponse("C1", "YARN", "RESOURCEMANAGER", "Host101", "INSTALLED", "", null, null, null);
    shr2.setMaintenanceState(MaintenanceState.ON.toString());
    ServiceComponentHostResponse shr3 = new ServiceComponentHostResponse("C1", "YARN", "NODEMANAGER", "Host100", "STARTED", "", null, null, null);
    shr3.setMaintenanceState(MaintenanceState.ON.toString());
    ServiceComponentHostResponse shr4 = new ServiceComponentHostResponse("C1", "YARN", "YARN_CLIENT", "Host100", "INSTALLED", "", null, null, null);
    shr4.setMaintenanceState(MaintenanceState.ON.toString());
    Set<ServiceComponentHostResponse> responses = new LinkedHashSet<ServiceComponentHostResponse>();
    responses.add(shr1);
    responses.add(shr2);
    responses.add(shr3);
    responses.add(shr4);
    // set expectations
    expect(managementController.getAmbariMetaInfo()).andReturn(ambariMetaInfo).anyTimes();
    expect(managementController.getClusters()).andReturn(clusters).anyTimes();
    expect(clusters.getCluster("C1")).andReturn(cluster).anyTimes();
    expect(managementController.getHostComponents((Set<ServiceComponentHostRequest>) anyObject())).andReturn(responses).anyTimes();
    expect(cluster.getDesiredStackVersion()).andReturn(stackId).anyTimes();
    expect(stackId.getStackName()).andReturn("S1").anyTimes();
    expect(stackId.getStackVersion()).andReturn("V1").anyTimes();
    expect(ambariMetaInfo.getComponent((String) anyObject(), (String) anyObject(), (String) anyObject(), (String) anyObject())).andReturn(componentInfo).anyTimes();
    expect(componentInfo.isClient()).andReturn(false);
    expect(componentInfo.isMaster()).andReturn(true);
    expect(componentInfo.isClient()).andReturn(false);
    expect(componentInfo.isMaster()).andReturn(true);
    expect(componentInfo.isClient()).andReturn(false);
    expect(componentInfo.isMaster()).andReturn(false);
    expect(componentInfo.isClient()).andReturn(false);
    expect(componentInfo.isClient()).andReturn(true);
    expect(componentInfo.isMaster()).andReturn(false);
    expect(componentInfo.isClient()).andReturn(true).times(2);
    // replay
    replay(managementController, clusters, cluster, ambariMetaInfo, stackId, componentInfo);
    ServiceResourceProvider.ServiceState serviceState = new ServiceResourceProvider.DefaultServiceState();
    State state = serviceState.getState(managementController, "C1", "YARN");
    Assert.assertEquals(State.STARTED, state);
    /*
     * All components are stopped, service is considered INSTALLED
     */
    reset(componentInfo);
    responses.clear();
    shr1 = new ServiceComponentHostResponse("C1", "YARN", "RESOURCEMANAGER", "Host100", "INSTALLED", "", null, null, null);
    shr1.setMaintenanceState(MaintenanceState.ON.toString());
    shr2 = new ServiceComponentHostResponse("C1", "YARN", "RESOURCEMANAGER", "Host101", "INSTALLED", "", null, null, null);
    shr2.setMaintenanceState(MaintenanceState.ON.toString());
    shr3 = new ServiceComponentHostResponse("C1", "YARN", "NODEMANAGER", "Host100", "INSTALLED", "", null, null, null);
    shr3.setMaintenanceState(MaintenanceState.ON.toString());
    shr4 = new ServiceComponentHostResponse("C1", "YARN", "YARN_CLIENT", "Host100", "INSTALLED", "", null, null, null);
    shr4.setMaintenanceState(MaintenanceState.ON.toString());
    responses.add(shr1);
    responses.add(shr2);
    responses.add(shr3);
    responses.add(shr4);
    expect(componentInfo.isClient()).andReturn(false);
    expect(componentInfo.isMaster()).andReturn(true);
    expect(componentInfo.isClient()).andReturn(false);
    expect(componentInfo.isMaster()).andReturn(true);
    expect(componentInfo.isClient()).andReturn(false);
    expect(componentInfo.isMaster()).andReturn(false);
    expect(componentInfo.isClient()).andReturn(false);
    expect(componentInfo.isClient()).andReturn(true);
    expect(componentInfo.isMaster()).andReturn(false);
    expect(componentInfo.isClient()).andReturn(true).times(2);
    replay(componentInfo);
    state = serviceState.getState(managementController, "C1", "YARN");
    Assert.assertEquals(State.INSTALLED, state);
}

@Test
public void testVisit() {
    ResourceProvider provider = createStrictMock(ResourceProvider.class);
    Capture<Set<String>> propertiesCapture = new Capture<Set<String>>();
    SimplifyingPredicateVisitor visitor = new SimplifyingPredicateVisitor(provider);
    //expectations
    expect(provider.checkPropertyIds(capture(propertiesCapture))).andReturn(Collections.<String>emptySet()).anyTimes();
    replay(provider);
    PredicateHelper.visit(PREDICATE_1, visitor);
    List<Predicate> simplifiedPredicates = visitor.getSimplifiedPredicates();
    Assert.assertEquals(1, simplifiedPredicates.size());
    Assert.assertEquals(PREDICATE_1, simplifiedPredicates.get(0));
    Set<String> setProps = propertiesCapture.getValue();
    assertEquals(1, setProps.size());
    assertEquals(PROPERTY_A, setProps.iterator().next());
    // ---
    PredicateHelper.visit(PREDICATE_3, visitor);
    simplifiedPredicates = visitor.getSimplifiedPredicates();
    Assert.assertEquals(1, simplifiedPredicates.size());
    Assert.assertEquals(PREDICATE_3, simplifiedPredicates.get(0));
    // ---
    PredicateHelper.visit(PREDICATE_4, visitor);
    simplifiedPredicates = visitor.getSimplifiedPredicates();
    Assert.assertEquals(2, simplifiedPredicates.size());
    Assert.assertEquals(PREDICATE_1, simplifiedPredicates.get(0));
    Assert.assertEquals(PREDICATE_2, simplifiedPredicates.get(1));
    // ---
    PredicateHelper.visit(PREDICATE_6, visitor);
    simplifiedPredicates = visitor.getSimplifiedPredicates();
    Assert.assertEquals(3, simplifiedPredicates.size());
    Assert.assertEquals(PREDICATE_5, simplifiedPredicates.get(0));
    Assert.assertEquals(PREDICATE_1, simplifiedPredicates.get(1));
    Assert.assertEquals(PREDICATE_2, simplifiedPredicates.get(2));
    // ---
    PredicateHelper.visit(PREDICATE_8, visitor);
    simplifiedPredicates = visitor.getSimplifiedPredicates();
    Assert.assertEquals(4, simplifiedPredicates.size());
    Assert.assertEquals(PREDICATE_5, simplifiedPredicates.get(0));
    Assert.assertEquals(PREDICATE_1, simplifiedPredicates.get(1));
    Assert.assertEquals(PREDICATE_2, simplifiedPredicates.get(2));
    Assert.assertEquals(PREDICATE_7, simplifiedPredicates.get(3));
    // ---
    PredicateHelper.visit(PREDICATE_9, visitor);
    simplifiedPredicates = visitor.getSimplifiedPredicates();
    Assert.assertEquals(4, simplifiedPredicates.size());
    //    Assert.assertEquals(???, simplifiedPredicates.get(0));
    // ---
    PredicateHelper.visit(PREDICATE_11, visitor);
    simplifiedPredicates = visitor.getSimplifiedPredicates();
    Assert.assertEquals(4, simplifiedPredicates.size());
    //    Assert.assertEquals(???, simplifiedPredicates.get(0));
    // ---
    PredicateHelper.visit(PREDICATE_16, visitor);
    simplifiedPredicates = visitor.getSimplifiedPredicates();
    Assert.assertEquals(1, simplifiedPredicates.size());
    Assert.assertEquals(PREDICATE_16, simplifiedPredicates.get(0));
    //reset assertions.  For property D, indicate that it is not supported.
    verify(provider);
    reset(provider);
    expect(provider.checkPropertyIds(capture(propertiesCapture))).andReturn(Collections.<String>emptySet());
    expect(provider.checkPropertyIds(capture(propertiesCapture))).andReturn(Collections.<String>singleton(PROPERTY_D));
    replay(provider);
    // ---
    PredicateHelper.visit(PREDICATE_13, visitor);
    simplifiedPredicates = visitor.getSimplifiedPredicates();
    Assert.assertEquals(1, simplifiedPredicates.size());
    Assert.assertEquals(PREDICATE_1, simplifiedPredicates.get(0));
    verify(provider);
    reset(provider);
    expect(provider.checkPropertyIds(capture(propertiesCapture))).andReturn(Collections.<String>emptySet()).anyTimes();
    replay(provider);
    // ---
    PredicateHelper.visit(PREDICATE_15, visitor);
    simplifiedPredicates = visitor.getSimplifiedPredicates();
    Assert.assertEquals(1, simplifiedPredicates.size());
    Assert.assertEquals(PREDICATE_1, simplifiedPredicates.get(0));
    verify(provider);
}

