    Gson gson = new Gson();
    for (StageEntity se : stages) {
        Map<String, String> map = gson.fromJson(se.getCommandParamsStage(), Map.class);
        assertTrue(map.containsKey("upgrade_direction"));
        assertEquals("downgrade", map.get("upgrade_direction"));
    }
}

