    Assert.assertEquals(schedule.getScheduleExpression(), cronTrigger.getCronExpression());
    Assert.assertEquals(jobName1, jobDetail1.getKey().getName());
    Assert.assertEquals(jobName2, jobDetail2.getKey().getName());
}

