public void testServiceConfigVersions() throws Exception {
    createDefaultCluster();
    Config config1 = configFactory.createNew(c1, "hdfs-site", new HashMap<String, String>() {

        {
            put("a", "b");
        }
    }, new HashMap<String, Map<String, String>>());
